// About P2P introduction videos — the text content (see routes/introVideos.ts).
// data/intro-videos/bundle.txt (JSON; bundled as text like the dictionary index) is generated by scripts/build-intro-videos.mjs from:
//   timing.json      — per video: duration, narration units (one sentence each, with the timings of its subtitle cues
//                      from the narrator's own voice) and on-screen text items (time, length, role, position);
//   lang/<code>.json — per language: titles, descriptions, one translation per unit and per on-screen text item, the
//                      review status of each asset, and the Bible translations quoted (with their licences).
// English is the original script and the source of truth.
import bundleText from "../../data/intro-videos/bundle.txt";

export type AssetKind = "subtitles" | "overlays" | "audio";
export type AssetStatus = "not_started" | "translated" | "audio_generated" | "awaiting_review" | "approved" | "published" | "withdrawn";

export interface IntroCue { t0: number; t1: number; len: number }
export interface IntroUnit { id: string; t0: number; t1: number; cues: IntroCue[] }
export interface IntroOverlay {
  id: string; t: number; len: number;
  /** lower (lower third), verse (centred quotation), title / panel-title / panel-sub (app demo captions), label, ref, outro */
  role: string;
  /** Position of the text block on the 1920×1080 frame: x/y as fractions, anchor = where (x,y) sits on the block. */
  x: number; y: number; w?: number; anchor: "top" | "middle" | "bottom"; align: "left" | "center"; size: number; color: "cream" | "gold" | "muted"; font: "serif" | "serif-italic" | "sans" | "sans-bold" | "script";
  scripture?: boolean; ref?: string; text?: string; brand?: boolean;
}
export interface IntroVideo { id: string; group: string; order: number; duration: number; units: IntroUnit[]; overlays: IntroOverlay[] }
export interface IntroLangVideo {
  title: string; description: string;
  units?: Record<string, string>; overlays?: Record<string, string>;
  status?: Partial<Record<AssetKind, AssetStatus>>;
}
export interface IntroLang { code: string; rtl?: boolean; scriptureSources?: { name: string; licence: string; credit: string }[]; videos: Record<string, IntroLangVideo> }

export interface IntroVoice { name: string; gender: "male" | "female" }
type Bundle = { version: string; timing: { videos: IntroVideo[] }; langs: Record<string, IntroLang>; voices?: Record<string, Record<string, IntroVoice>> };
let parsed: Bundle | null = null;
const B_ = (): Bundle => (parsed ??= JSON.parse(bundleText) as Bundle);
/** The narrator of a film in a voice-over language (for the player's Voice menu), if known. */
export function introVoice(videoId: string, code: string): IntroVoice | null { return B_().voices?.[code]?.[videoId] ?? null; }
/** Every recorded voice of a film in a language: key "de" (first voice), "de-2" (second voice, the other gender). */
export function introVoices(videoId: string, lang: string): (IntroVoice & { key: string })[] {
  return Object.entries(B_().voices ?? {})
    .filter(([key, per]) => (key.endsWith("-2") ? key.slice(0, -2) : key) === lang && per[videoId])   // "zh-TW" is a language, "-2" a second voice
    .sort(([a], [b]) => a.length - b.length || a.localeCompare(b))
    .map(([key, per]) => ({ key, ...per[videoId] }));
}

/** Languages with content files (each still needs PUBLISHED assets before members see it). */
export function introLangs(): string[] { return Object.keys(B_().langs); }
export function introTiming(): { version: string; videos: IntroVideo[] } { const b = B_(); return { version: b.version, videos: b.timing.videos }; }
export function introLang(code: string): IntroLang | undefined { return B_().langs[code]; }

const NO_SPACES = /[぀-ヿ㐀-鿿豈-﫿฀-๿]/;   // Japanese, Chinese, Thai: split by characters

/** One translated sentence → the unit's subtitle cues (same timings), divided in proportion to the original lengths. */
export function splitUnit(u: IntroUnit, text: string): { t0: number; t1: number; text: string }[] {
  const t = (text ?? "").trim();
  if (!t) return [];
  if (u.cues.length <= 1) return [{ t0: u.t0, t1: u.t1, text: wrap(t) }];
  const total = u.cues.reduce((s, c) => s + c.len, 0) || 1;
  const chars = NO_SPACES.test(t);
  const words = chars ? Array.from(t) : t.split(/\s+/);
  const out: { t0: number; t1: number; text: string }[] = [];
  let wi = 0, acc = 0;
  const L = Array.from(t).length;
  for (let k = 0; k < u.cues.length; k++) {
    acc += u.cues[k].len;
    const target = k === u.cues.length - 1 ? L : Math.round((acc / total) * L);
    const part: string[] = [];
    let n = out.reduce((s, c) => s + Array.from(c.text.replace(/\n/g, chars ? "" : " ")).length + (chars ? 0 : 1), 0);
    while (wi < words.length && (k === u.cues.length - 1 || n + Array.from(words[wi]).length / 2 <= target || part.length === 0)) {
      part.push(words[wi]); n += Array.from(words[wi]).length + (chars ? 0 : 1); wi++;
    }
    if (part.length) out.push({ t0: u.cues[k].t0, t1: u.cues[k].t1, text: wrap(part.join(chars ? "" : " ")) });
    else if (out.length) out[out.length - 1].t1 = u.cues[k].t1;   // nothing left for this cue: keep the previous line on screen
  }
  return out;
}

/** Two lines at most, broken near the middle (as the original subtitles are). */
function wrap(t: string): string {
  const a = Array.from(t);
  if (a.length <= 44) return t;
  if (NO_SPACES.test(t)) { const m = Math.ceil(a.length / 2); return a.slice(0, m).join("") + "\n" + a.slice(m).join(""); }
  const mid = t.lastIndexOf(" ", Math.floor(t.length / 2) + 6);
  return mid > 0 ? t.slice(0, mid) + "\n" + t.slice(mid + 1) : t;
}
